import{_ as n,o as a,c as e,a0 as l}from"./chunks/framework.DqMqoJl9.js";const b=JSON.parse('{"title":"undefined","description":"","frontmatter":{},"headers":[],"relativePath":"jsApi/valueProperty/undefined.md","filePath":"jsApi/valueProperty/undefined.md","lastUpdated":1791573371000}'),p={name:"jsApi/valueProperty/undefined.md"};function t(o,s,r,i,c,d){return a(),e("div",null,[...s[0]||(s[0]=[l(`<p><a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/undefined" target="_blank">原文链接</a><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/undefined" target="_blank">en</a></p><h1 id="undefined" tabindex="-1">undefined <a class="header-anchor" href="#undefined" aria-label="Permalink to &quot;undefined&quot;">​</a></h1><p>全局属性undefined表示原始值undefined。它是一个JavaScript的 原始数据类型</p><table tabindex="0"><thead><tr><th style="text-align:left;">属性</th><th style="text-align:left;"></th></tr></thead><tbody><tr><td style="text-align:left;">writable</td><td style="text-align:left;">false</td></tr><tr><td style="text-align:left;">enumerable</td><td style="text-align:left;">false</td></tr><tr><td style="text-align:left;">configurable</td><td style="text-align:left;">false</td></tr></tbody></table><h2 id="_1、语法" tabindex="-1">1、语法 <a class="header-anchor" href="#_1、语法" aria-label="Permalink to &quot;1、语法&quot;">​</a></h2><p><code>undefined </code></p><h2 id="_2、描述" tabindex="-1">2、描述 <a class="header-anchor" href="#_2、描述" aria-label="Permalink to &quot;2、描述&quot;">​</a></h2><p>undefined是全局对象的一个属性。也就是说，它是全局作用域的一个变量。undefined的最初值就是原始数据类型undefined。</p><p>在现代浏览器（<code>JavaScript 1.8.5/Firefox 4+</code>），自<code>ECMAscript5</code>标准以来undefined是一个不能被配置（<code>non-configurable</code>）， 不能被重写（non-writable）的属性。即便事实并非如此，也要避免去重写它。</p><p>一个没有被赋值的变量是undefined类型。一个方法或者是语句如果在执行期间没有变量被赋值也会返回undefined（对于这句话持疑惑态度，请查看英文原文来理解）。 一个函数如果没有返回值，就会返回一个undefined值。</p><p><code>但是它可能被使用作为一个标识符（变量名）在任何作用域中，而不仅仅是在全局作用域中(因为undefined不是一个保留字))，这样做是一个非常坏的主意，因为这样会使你的代码难以去维护和排错。</code></p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">// 不要这样做！</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 打印 &#39;foo string&#39; PS：说明undefined的值和类型都已经改变</span></span>
<span class="line"><span style="color:#24292E;">(</span><span style="color:#D73A49;">function</span><span style="color:#24292E;">() {</span></span>
<span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> undefined </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> &#39;foo&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">undefined</span><span style="color:#24292E;">, </span><span style="color:#D73A49;">typeof</span><span style="color:#005CC5;"> undefined</span><span style="color:#24292E;">)</span></span>
<span class="line"><span style="color:#24292E;">})()</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 打印 &#39;foo string&#39; PS：说明undefined的值和类型都已经改变</span></span>
<span class="line"><span style="color:#24292E;">(</span><span style="color:#D73A49;">function</span><span style="color:#24292E;">(</span><span style="color:#E36209;">undefined</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">undefined</span><span style="color:#24292E;">, </span><span style="color:#D73A49;">typeof</span><span style="color:#005CC5;"> undefined</span><span style="color:#24292E;">)</span></span>
<span class="line"><span style="color:#24292E;">})(</span><span style="color:#032F62;">&#39;foo&#39;</span><span style="color:#24292E;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h2 id="_3、示例" tabindex="-1">3、示例 <a class="header-anchor" href="#_3、示例" aria-label="Permalink to &quot;3、示例&quot;">​</a></h2><h3 id="_1-严格相等和undefined" tabindex="-1">(1) 严格相等和undefined <a class="header-anchor" href="#_1-严格相等和undefined" aria-label="Permalink to &quot;(1) 严格相等和undefined&quot;">​</a></h3><p>你可以使用undefined和严格相等或不相等操作符来决定一个变量是否拥有值。在下面的代码中，变量x是未定义的，if 语句的求值结果将是true</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> x;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">if</span><span style="color:#24292E;"> (x </span><span style="color:#D73A49;">===</span><span style="color:#005CC5;"> undefined</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#6A737D;">// 执行这些语句</span></span>
<span class="line"><span style="color:#24292E;">} </span><span style="color:#D73A49;">else</span><span style="color:#24292E;"> {</span></span>
<span class="line"><span style="color:#6A737D;">// 这些语句不会被执行</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><code>注意：这里是必须使用严格相等操作符（===）而不是标准相等操作符（==），因为 x == undefined 会检查x是不是null，但是严格相等不会检查。null 和 undefined是不相等的。移步比较操作符查看详情。</code></p><h3 id="_2-typeof-操作符和undefined" tabindex="-1">(2) Typeof 操作符和undefined <a class="header-anchor" href="#_2-typeof-操作符和undefined" aria-label="Permalink to &quot;(2) Typeof 操作符和undefined&quot;">​</a></h3><p>可替换的是，typeof可以被使用：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> x;</span></span>
<span class="line"><span style="color:#D73A49;">if</span><span style="color:#24292E;">(</span><span style="color:#D73A49;">typeof</span><span style="color:#24292E;"> x </span><span style="color:#D73A49;">===</span><span style="color:#032F62;"> &#39;undefined&#39;</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#6A737D;">    // 执行这些语句</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>还有一个原因去使用 typeof的是它不会在一个变量没有被声明的时候抛出一个错误。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">// 这里没有声明x</span></span>
<span class="line"><span style="color:#D73A49;">if</span><span style="color:#24292E;">(</span><span style="color:#D73A49;">typeof</span><span style="color:#24292E;"> x </span><span style="color:#D73A49;">===</span><span style="color:#032F62;"> &#39;undefined&#39;</span><span style="color:#24292E;">) { </span><span style="color:#6A737D;">// 没有错误，执行结果为true</span></span>
<span class="line"><span style="color:#6A737D;">    // 执行这些语句</span></span>
<span class="line"><span style="color:#24292E;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">if</span><span style="color:#24292E;">(x </span><span style="color:#D73A49;">===</span><span style="color:#005CC5;"> undefined</span><span style="color:#24292E;">) { </span><span style="color:#6A737D;">// 抛出一个错误，ReferenceError</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>但是，技术方面看来这样的使用方法应该被避免。JavaScript是一个静态作用域语言，所以可以知道，一个变量是否可以被读取只要看它是否在一个封闭的上下文中被声明。 唯一的例外是全局作用域，但是全局作用域是被绑定在全局对象上的，所以检查一个变量是否在全局上下文中存在只要检查全局对象上面是否存在这个属性（使用in操作符）。</p><h3 id="_3-void操作符和undefined" tabindex="-1">(3) Void操作符和undefined <a class="header-anchor" href="#_3-void操作符和undefined" aria-label="Permalink to &quot;(3) Void操作符和undefined&quot;">​</a></h3><p>void 操作符是第三种可以替代的方法。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> x;</span></span>
<span class="line"><span style="color:#D73A49;">if</span><span style="color:#24292E;">(x </span><span style="color:#D73A49;">===</span><span style="color:#D73A49;"> void</span><span style="color:#005CC5;"> 0</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#6A737D;">    // 执行这些语句</span></span>
<span class="line"><span style="color:#24292E;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 没有声明y</span></span>
<span class="line"><span style="color:#D73A49;">if</span><span style="color:#24292E;">(y </span><span style="color:#D73A49;">===</span><span style="color:#D73A49;"> void</span><span style="color:#005CC5;"> 0</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#6A737D;">    // 抛出一个RenferenceError错误(与\`typeof\`相比)</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h2 id="_4、规范" tabindex="-1">4、规范 <a class="header-anchor" href="#_4、规范" aria-label="Permalink to &quot;4、规范&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Specification</th><th style="text-align:left;">Status</th><th style="text-align:left;">Comment</th></tr></thead><tbody><tr><td style="text-align:left;">ECMAScript 1st Edition (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;">Initial definition JavaScript 1.3</td></tr><tr><td style="text-align:left;">ECMAScript 5.1 (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">ECMAScript 2015 (6th Edition, ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr></tbody></table>`,28)])])}const y=n(p,[["render",t]]);export{b as __pageData,y as default};
